cd /opt/nxeon && cat > /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/board-inspect.mjs <<'EOF'
import { PrismaClient } from '@prisma/client';
const db = new PrismaClient();
const board = await db.board.findFirst({ where: { name: 'Nxeon' }, include: { columns: { orderBy: { position: 'asc' } } } });
if (!board) { console.log('NO BOARD NAMED Nxeon'); process.exit(1); }
console.log('BOARD', board.id, board.name);
console.log('COLUMNS:', board.columns.map(c => `${c.name}(${c.id})[pos${c.position}]`).join(', '));
const cards = await db.card.findMany({ where: { boardId: board.id, archivedAt: null }, select: { id: true, title: true, columnId: true, position: true } });
for (const c of cards) {
  const col = board.columns.find(x => x.id === c.columnId);
  console.log(`CARD "${c.title}" id=${c.id} col=${col?.name} pos=${c.position}`);
}
await db.$disconnect();
EOF
node /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/board-inspect.mjs 2>&1

